        title.setText(text("音频设备设置"),juce::dontSendNotification);title.setFont(juce::FontOptions(22,juce::Font::bold));outputLabel.setText(text("输出设备"),juce::dontSendNotification);inputLabel.setText(text("输入设备"),juce::dontSendNotification);rateLabel.setText(text("设备采样率"),juce::dontSendNotification);bufferLabel.setText(text("缓冲大小"),juce::dontSendNotification);inputChannelsLabel.setText(text("启用输入通道"),juce::dontSendNotification);outputChannelsLabel.setText(text("启用输出通道"),juce::dontSendNotification);
        output.setComponentID("audio.settings.output");input.setComponentID("audio.settings.input");rate.setComponentID("audio.settings.rate");buffer.setComponentID("audio.settings.buffer");applyButton.setComponentID("audio.settings.apply");refreshButton.setComponentID("audio.settings.refresh");closeButton.setComponentID("audio.settings.close");result.setComponentID("audio.settings.result");actual.setComponentID("audio.settings.actual");
        inputView.setViewedComponent(&inputRows,false);outputView.setViewedComponent(&outputRows,false);inputView.setScrollBarsShown(true,false);outputView.setScrollBarsShown(true,false);
