        const auto& s=state["actual"];actual.setText(s["open"].get<bool>()?text("当前实际：")+text(s["output"].get<std::string>())+" · "+juce::String(s["sample_rate"].get<double>()/1000.,1)+" kHz / "+juce::String(s["buffer_frames"].get<int>())+text(" 帧"):text("当前没有打开的音频设备"),juce::dontSendNotification);
