        title.setBounds(x,y,w-180,32);closeButton.setBounds(x+w-80,y,80,29);refreshButton.setBounds(x+w-174,y,84,29);backend.setBounds(x,y+43,w,22);actual.setBounds(x,y+72,w,40);
