        auto rows=[this,initial](juce::Component& holder,juce::OwnedArray<juce::ToggleButton>& buttons,const char* side,const char* names){buttons.clear();const bool same=initial&&caps["selection"][side]==facts["actual"][side];int n=0;for(const auto& name:caps[names]){if(n>=caps["max_native_channels"].get<int>())break;auto* b=buttons.add(new juce::ToggleButton(juce::String(n+1)+" · "+text(name.get<std::string>())));b->setComponentID(text(std::string("audio.settings.")+side+".channel:"+std::to_string(n)));const auto& active=facts["actual"][std::string(side)+"_channels"];b->setToggleState(same?std::find(active.begin(),active.end(),Json(n))!=active.end():std::string(side)=="output"?n<2:true,juce::dontSendNotification);b->onClick=[this]{updateRuntime(facts);};holder.addAndMakeVisible(b);++n;}};
