    void updateBudget(){int r=rate.getSelectedId()-1,b=buffer.getSelectedId()-1;if(r<0||r>=int(rates.size())||b<0||b>=int(buffers.size())){detail.setText(text("设备能力不可用 · 请刷新"),juce::dontSendNotification);return;}auto period=1000.*buffers[b].get<int>()/rates[r].get<double>();detail.setText(text("单缓冲时长 ")+juce::String(period,2)+text(" ms；这不是实际往返延迟。\n关闭输入监听后配置；工程时间轴仍为 48 kHz。"),juce::dontSendNotification);}
    std::string lastReceipt;Inventory inventory;Capabilities capabilities;Apply apply;std::function<void()> close;Json facts,caps=nullptr,baseline;bool runtimeEnabled=false,busy=false;std::vector<std::string> outputs,inputs;std::vector<Json> rates,buffers;
    juce::Rectangle<int> card;juce::Label title,backend,actual,outputLabel,inputLabel,rateLabel,bufferLabel,inputChannelsLabel,outputChannelsLabel,detail,result;juce::ComboBox output,input,rate,buffer;juce::Component inputRows,outputRows;juce::OwnedArray<juce::ToggleButton> inputButtons,outputButtons;juce::Viewport inputView,outputView;juce::TextButton refreshButton{text("刷新")},applyButton{text("应用设备设置")},closeButton{text("关闭")};
